const domains=['Jaringan','Server & Virtualisasi','Keamanan','Backup & Recovery','Data Center','Monitoring'];
const seed=[['Redundansi core switch belum tersedia','Jaringan',2,5,'Kritis','Tim Network','2026-11-30','Sediakan jalur dan perangkat core cadangan.','Dalam proses'],['Uji pemulihan backup belum berkala','Backup & Recovery',2,5,'Kritis','Tim System','2026-11-15','Susun jadwal simulasi restore dan dokumentasikan hasilnya.','Belum dimulai'],['Segmentasi jaringan perlu ditingkatkan','Keamanan',2.5,4.5,'Tinggi','Tim Security','2026-12-15','Tinjau segmentasi dan aturan akses antar zona.','Dalam proses'],['Kapasitas cluster virtualisasi terbatas','Server & Virtualisasi',3,4.5,'Tinggi','Tim System','2026-12-20','Evaluasi kapasitas dan rencanakan ekspansi cluster.','Belum dimulai'],['Pemantauan lingkungan ruang server','Data Center',3.5,4.5,'Sedang','Tim Infrastruktur','2026-12-10','Lengkapi sensor suhu dan notifikasi lingkungan.','Dalam proses'],['Sentralisasi log perangkat jaringan','Monitoring',3,4,'Sedang','Tim Network','2026-11-25','Integrasikan sumber log ke dashboard monitoring.','Dalam proses'],['Dokumentasi topologi belum mutakhir','Jaringan',3.5,4,'Rendah','Tim Network','2026-11-10','Perbarui diagram topologi dan inventaris koneksi.','Selesai'],['Pemantauan penggunaan storage','Monitoring',3,4,'Tinggi','Tim System','2026-11-20','Buat ambang peringatan dan evaluasi tren kapasitas.','Belum dimulai']].map((r,i)=>Object.fromEntries(['title','domain','actual','target','priority','owner','due','action','status'].map((k,j)=>[k,r[j]]).concat([['id',i+1]])));
let records;try{records=JSON.parse(localStorage.getItem('bai-gap-v1'))||seed}catch{records=seed}let editing=null,page='Dashboard';const $=id=>document.getElementById(id),colors={Kritis:'#c76a54',Tinggi:'#d3a35b',Sedang:'#71a798',Rendah:'#a9c6d0'};const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
domains.forEach(d=>$('domain').add(new Option(d,d)));
function persist(){localStorage.setItem('bai-gap-v1',JSON.stringify(records));render()}
function render(){const open=records.filter(r=>r.status!=='Selesai'),avg=records.length?records.reduce((s,r)=>s+Number(r.actual),0)/records.length:0,target=records.length?records.reduce((s,r)=>s+Number(r.target),0)/records.length:0,ready=target?Math.round(avg/target*100):0;
$('stats').innerHTML=[['Kesiapan infrastruktur',ready+'%','Skor aktual '+avg.toFixed(1)+' dari target '+target.toFixed(1),'◈'],['Total assessment',records.length,'Mencakup '+new Set(records.map(r=>r.domain)).size+' domain infrastruktur','▤'],['Gap prioritas kritis',open.filter(r=>r.priority==='Kritis').length,'Memerlukan perhatian segera','⚑'],['Perbaikan selesai',records.filter(r=>r.status==='Selesai').length,'Dari '+records.length+' rencana perbaikan','✓']].map(([l,v,s,i])=>`<div class="stat"><div class="label">${l}<span>${i}</span></div><b>${v}</b><small>${s}</small></div>`).join('');
$('bars').innerHTML=domains.map(d=>{const rr=records.filter(r=>r.domain===d),a=rr.length?rr.reduce((s,r)=>s+ +r.actual,0)/rr.length:0,t=rr.length?rr.reduce((s,r)=>s+ +r.target,0)/rr.length:0;return `<div class="barrow"><span>${d}</span><div class="track" style="width:${t/5*100}%"><i style="width:${t?a/t*100:0}%"></i></div><b>${a.toFixed(1)} / ${t.toFixed(1)}</b></div>`}).join('');
const gaps=records.filter(r=>r.target>r.actual);$('gapcount').textContent=gaps.length;let acc=0;const slices=Object.entries(colors).map(([p,c])=>{const n=gaps.filter(r=>r.priority===p).length,start=acc;acc+=gaps.length?n/gaps.length*100:0;return `${c} ${start}% ${acc}%`});$('donut').style.background=gaps.length?`conic-gradient(${slices.join(',')})`:'#e3eeea';$('priorities').innerHTML=Object.entries(colors).map(([p,c])=>`<div class="priorityline"><span><i style="background:${c}"></i>${p}</span><b>${gaps.filter(r=>r.priority===p).length} <span>gap</span></b></div>`).join('');
const filtered=records.filter(r=>(!$('domain').value||r.domain===$('domain').value)&&(!$('priority').value||r.priority===$('priority').value)&&(`${r.title} ${r.owner}`.toLowerCase().includes($('search').value.toLowerCase()))&&(page!=='Rencana Aksi'||r.status!=='Selesai'));
$('rows').innerHTML=filtered.map(r=>`<tr><td><strong>${esc(r.title)}</strong><small>${esc(r.domain)} · GAP-${String(r.id).padStart(3,'0')}</small></td><td>${r.actual} <span style="color:#a2b4b9">→</span> ${r.target}</td><td><b>${Math.max(0,r.target-r.actual).toFixed(1)}</b></td><td><span class="badge ${r.priority}">${r.priority}</span></td><td>${esc(r.owner)}<small>${esc(r.due)}</small></td><td><span class="status">● ${esc(r.status)}</span></td><td><button data-id="${r.id}" aria-label="Edit assessment">↗</button></td></tr>`).join('')||'<tr><td colspan="7">Tidak ada temuan yang sesuai filter.</td></tr>';$('recordcount').textContent=records.length+' assessment';$('shown').textContent=`Menampilkan ${filtered.length} dari ${records.length} assessment`;
$('report').innerHTML=`<article><div class="eyebrow">RINGKASAN ASSESSMENT • DATA DEMONSTRASI</div><h1>Laporan Kesiapan Infrastruktur</h1><p>${records.length} assessment • Kesiapan ${ready}% • ${open.length} rencana belum selesai</p><p>Skor kesiapan = total skor aktual ÷ total skor target × 100%. Gap = maksimum(0, target − aktual). Prioritas ditentukan oleh assessor.</p><button onclick="exportCSV()">↓ Unduh laporan CSV</button></article>`;
}
function openForm(id){editing=id??null;$('form').reset();const r=records.find(x=>x.id===id);$('formtitle').textContent=r?'Detail assessment':'Tambah assessment';$('deletebtn').hidden=!r;if(r)for(const [k,v]of Object.entries(r)){if($('form').elements[k])$('form').elements[k].value=v}else{$('form').elements.actual.value=1;$('form').elements.target.value=5}$('editor').showModal()}
$('form').onsubmit=e=>{e.preventDefault();const r=Object.fromEntries(new FormData(e.target));r.actual=+r.actual;r.target=+r.target;if(r.actual>r.target){toast('Target harus sama atau lebih tinggi dari skor aktual.');return}r.id=editing??Date.now();if(editing)records=records.map(x=>x.id===editing?r:x);else records.push(r);try{persist();$('editor').close();toast('Assessment berhasil disimpan.')}catch{toast('Penyimpanan browser tidak tersedia. Ekspor data untuk menyimpan salinan.')}};
function removeRecord(){if(!confirm('Hapus assessment ini?'))return;records=records.filter(x=>x.id!==editing);persist();$('editor').close();toast('Assessment dihapus.')}
function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',4000)}
function exportCSV(){const keys=['id','title','domain','actual','target','priority','owner','due','action','status'];const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const csv='\uFEFF'+[keys.join(','),...records.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='BAI-gap-analysis.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{page=b.dataset.page;document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x===b));$('crumb').textContent=page;$('title').textContent=page==='Dashboard'?'Dashboard Infrastruktur':page;$('dashboard').hidden=page!=='Dashboard';$('report').hidden=page!=='Laporan';$('register').hidden=page==='Laporan';$('tabletitle').textContent=page==='Rencana Aksi'?'Rencana aksi terbuka':'Register kesenjangan';render()});['search','domain','priority'].forEach(id=>$(id).addEventListener('input',render));$('rows').onclick=e=>{const b=e.target.closest('[data-id]');if(b)openForm(Number(b.dataset.id))};render();
